{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Nifedipine has an absolute oral bioavailability of 0.43 ± 0.14 versus IV in humans, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Isradipine systemic availability in healthy volunteers is about 16.5%, below the 20% threshold, indicating significant first-pass metabolism.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Isradipine absolute bioavailability versus intravenous infusion was 0.28 in healthy young volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "The pyrazolopyrimidinone analogue showed 34% oral bioavailability in healthy volunteers in the fasted state, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Elagolix is reported to have good oral bioavailability in humans, consistent with F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "The active metabolite of nabumetone had a mean absolute bioavailability of 38% in healthy subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most highly transferable experimental analogues show oral bioavailability at or above 20%, including absolute measurements for nifedipine (~43%), isradipine (28% absolute), the pyrazolopyrimidinone (34%), and nabumetone metabolite (38%). The main contradictory evidence is isradipine systemic availability of ~16-19% in healthy volunteers, but its absolute F was above 20% and cirrhosis increases it to ~37%. Weighted evidence supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "Query structure is omitted, limiting structural analogy assessment beyond supplied transfer scores.",
    "Isradipine evidence is mixed: low systemic availability in healthy volunteers but higher absolute F and increased F in cirrhosis."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

